import java.util.Scanner;

public class RibbonCut {
    // HCF and LCM of two ribbon lengths of an imagined craft lesson
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter two lengths:");
        int a = sc.nextInt();
        int b = sc.nextInt();
        int hcf = 1;
        for (int i = 1; i <= a && i <= b; i++) {
            if (a % i == 0 && b % i == 0)
                hcf = i;           // the last common factor is the largest
        }
        int lcm = a * b / hcf;
        System.out.println("HCF = " + hcf);
        System.out.println("LCM = " + lcm);
    }
}
