import java.util.Scanner;

public class PrimePlots {
    // Lists the prime plot numbers between two limits (nested for loops)
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter the lower and the upper limit:");
        int m = sc.nextInt();
        int n = sc.nextInt();
        int count = 0;
        for (int i = m; i <= n; i++) {
            if (i < 2)
                continue;
            boolean prime = true;
            for (int j = 2; j < i; j++) {
                if (i % j == 0) {
                    prime = false;
                    break;
                }
            }
            if (prime) {
                System.out.print(i + " ");
                count++;
            }
        }
        System.out.println();
        System.out.println("Count = " + count);
    }
}
