import java.util.Scanner;

public class SeriesFair {
    // Sum of 1 + x/2 + x^2/3 + x^3/4 + ... to n terms for a maths-fair stall
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter x and the number of terms:");
        double x = sc.nextDouble();
        int n = sc.nextInt();
        double sum = 0;
        for (int i = 1; i <= n; i++)
            sum += Math.pow(x, i - 1) / i;   // term i is x to the power (i - 1), divided by i
        System.out.println("Sum = " + sum);
    }
}
